def is_prime(n):
    if n < 2: return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def search_primes(limit):
    results = []
    for q in range(2, limit):
        if is_prime(q):
            val = q*q - q + 1
            # Check if val is a perfect cube
            p = round(val**(1/3))
            if p**3 == val:
                if is_prime(p) and p != q:
                    results.append((q, p))
    return results

print(search_primes(10000))

def search_p(limit):
    results = []
    for p in range(2, limit):
        if is_prime(p):
            # q^2 - q + (1 - p^3) = 0
            # q = (1 +/- sqrt(1 - 4(1 - p^3))) / 2
            # q = (1 +/- sqrt(4p^3 - 3)) / 2
            disc = 4 * p**3 - 3
            root = int(disc**0.5)
            if root * root == disc:
                q1 = (1 + root) // 2
                if (1 + root) % 2 == 0 and is_prime(q1) and q1 != p:
                    results.append((q1, p))
                q2 = (1 - root) // 2
                if (1 - root) % 2 == 0 and is_prime(q2) and q2 != p:
                    results.append((q2, p))
    return results

